SELECT CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, o.customer_id, MIN(p.paid_at) AS first_paid_at, MIN(p.amount) AS min_amount FROM payments p JOIN orders o ON p.order_id = o.id WHERE o.order_date BETWEEN '2025-08-23' AND '2025-09-01' GROUP BY CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END, o.customer_id ORDER BY o.customer_id;
